import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"Search testing — kiwa SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/search-testing.md","filePath":"concepts/search-testing.md"}'),s={name:"concepts/search-testing.md"};function i(c,e,n,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="search-testing-—-kiwa-ssot" tabindex="-1">Search testing — kiwa SSOT <a class="header-anchor" href="#search-testing-—-kiwa-ssot" aria-label="Permalink to &quot;Search testing — kiwa SSOT&quot;">​</a></h1><h2 id="why-search-is-hard-to-test-against-the-real-server" tabindex="-1">Why search is hard to test against the real server <a class="header-anchor" href="#why-search-is-hard-to-test-against-the-real-server" aria-label="Permalink to &quot;Why search is hard to test against the real server&quot;">​</a></h2><ul><li><strong>cold start</strong> — a real Meili / Algolia / Typesense instance takes seconds to warm. Multiplied across a test matrix, that&#39;s minutes wasted per run.</li><li><strong>network-shaped</strong> — all three are HTTP-first. Every test call is a real fetch. Flaky when the CI network drops.</li><li><strong>ranking non-determinism</strong> — real servers may re-rank on typo distance, term frequency, position, custom rules. Assertions on <code>hits[0].id === expected</code> become brittle.</li></ul><p><code>@kiwa-lab/search</code> moves the query path in-process with deterministic ranking so the same test can gate CI.</p><h2 id="the-searchadapter-contract" tabindex="-1">The <code>SearchAdapter</code> contract <a class="header-anchor" href="#the-searchadapter-contract" aria-label="Permalink to &quot;The `SearchAdapter` contract&quot;">​</a></h2><p>Five ops. All three providers implement the same shape.</p><ul><li><code>addDocuments(index, docs)</code> — upsert (returns inserted count for net-new IDs)</li><li><code>updateDocuments(index, docs)</code> — partial merge (existing fields preserved)</li><li><code>deleteDocuments(index, ids)</code> — returns deleted count</li><li><code>search(index, { q, filter, facets, sort, limit, offset })</code></li><li><code>clearIndex(index)</code></li></ul><p>Plus <code>getIndexStats(index) → { docCount }</code> for assertions.</p><h2 id="the-ranking-model" tabindex="-1">The ranking model <a class="header-anchor" href="#the-ranking-model" aria-label="Permalink to &quot;The ranking model&quot;">​</a></h2><p><code>SearchEngine</code> uses <strong>word-overlap scoring</strong> — the fraction of query tokens that match the document&#39;s string fields. Ties broken by insertion order (stable).</p><ul><li>Query tokens: lowercased, split on whitespace + punctuation.</li><li>Match: exact token match in any string field of the document.</li><li>Score: <code>matches / query.tokens.length</code>.</li><li>Sort key: <code>{score desc, insertion_order asc}</code> unless <code>sort</code> overrides.</li></ul><p>This is intentionally simpler than real BM25 / TF-IDF. Tests assert on relative order, not absolute score, so the SUT stays free to swap real ranking algorithms without breaking specs.</p><h2 id="typo-tolerance" tabindex="-1">Typo tolerance <a class="header-anchor" href="#typo-tolerance" aria-label="Permalink to &quot;Typo tolerance&quot;">​</a></h2><p>1-edit-distance heuristic (single insertion / deletion / substitution). Provider defaults match production behaviour:</p><table tabindex="0"><thead><tr><th>provider</th><th>typo default</th><th>rationale</th></tr></thead><tbody><tr><td>Meilisearch</td><td>ON</td><td>Meili&#39;s <code>typoTolerance.enabled = true</code> is the default</td></tr><tr><td>Algolia</td><td>ON</td><td>Algolia&#39;s <code>typoTolerance</code> is <code>true</code></td></tr><tr><td>Typesense</td><td>OFF</td><td>Typesense&#39;s <code>num_typos = 0</code> is the common production choice</td></tr></tbody></table><p>Override per test: <code>createMeilisearchMock({ typoTolerance: false })</code>.</p><h2 id="filter-facet-sort-semantics" tabindex="-1">Filter / facet / sort semantics <a class="header-anchor" href="#filter-facet-sort-semantics" aria-label="Permalink to &quot;Filter / facet / sort semantics&quot;">​</a></h2><ul><li><strong><code>filter</code></strong> — plain object of exact-match key/value pairs. No <code>&gt;</code> / <code>&lt;</code> / <code>IN</code> — real providers use provider-specific filter DSLs, which the mock does NOT parse. If your SUT uses the DSL directly, test that path against the real server.</li><li><strong><code>facets</code></strong> — array of field names to bucket. Returned as <code>facetDistribution: Record&lt;field, Record&lt;value, count&gt;&gt;</code>.</li><li><strong><code>sort</code></strong> — array of field names, prefix <code>-</code> for descending. Multiple fields sorted in order.</li></ul><h2 id="when-not-to-use-the-mock" tabindex="-1">When NOT to use the mock <a class="header-anchor" href="#when-not-to-use-the-mock" aria-label="Permalink to &quot;When NOT to use the mock&quot;">​</a></h2><ul><li>Testing the actual DSL (<code>&gt; &lt; IN facetFilters</code>) — mock does not parse DSL. Use the real provider.</li><li>Testing async index build performance — mock is synchronous.</li><li>Testing multi-index cross-search — mock is single-index-per-call.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tutorials/13-search">Tutorial 13 — Search mock</a></li><li><a href="https://www.npmjs.com/package/@kiwa-lab/search" target="_blank" rel="noreferrer"><code>@kiwa-lab/search</code> on npm</a></li></ul>',22)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
